 @Test void actualCapsuleHitPublishesHudStopSourceTimerThenNativeNegAsrRecoil()throws Exception{for(var a:actual()){var h=new Host(a);capsule(h,2);h.walk();assertEquals(0,h.level.updateHudTime());assertEquals(4,h.placement.pool().state(127).routine());assertEquals(120,h.placement.pool().state(127).unsignedByte(LEVEL_END_TIMER));assertEquals(200,h.frame.state().motion().yVelocity());assertEquals(400,h.frame.state().motion().xVelocity());h.finish();}}
 @Test void actualNotRolledGateDoesNotReadTheLaterHitFieldsOrStopClock()throws Exception{for(var a:actual()){var h=new Host(a,0,0,2);capsule(h,2);h.walk();assertEquals(1,h.level.updateHudTime());assertEquals(2,h.placement.pool().state(127).routine());}}
 @Test void capsuleControlBsetPreservesOtherBitsAndUsesOriginalKnownClockAfterChildStore()throws Exception{for(var a:actual()){var h=new Host(a);capsule(h,6);h.placement.pool().write(h.placement.pool().state(127).moveByte(LEVEL_END_TIMER,1));h.walk();assertEquals(0xA1,h.frame.environment().controls().controlLocked());assertEquals(8,h.frame.environment().controls().logicalHeld());assertEquals(8,h.frame.environment().controls().logicalTap());assertEquals(50000,h.bonus.orElseThrow().timeBonusWord());assertTrue(h.placement.pool().capture().slots().stream().anyMatch(x->x.id()==0x3A));}}
 @Test void missingClockStopsAtFirstMinuteAfterActualMusicControlsAndResultsAllocation()throws Exception{for(var a:actual()){var h=new Host(a);h.live=CdCheckpointLiveAux.unknown();capsule(h,6);h.placement.pool().write(h.placement.pool().state(127).moveByte(LEVEL_END_TIMER,1));var e=assertThrows(SonicCdAct3FutureObjectPass.Unowned.class,h::walk);assertEquals(SonicCdAct3FutureObjectPass.Boundary.END_CLOCK,e.boundary());assertEquals(CdCheckpointLiveAux.TimeByte.MINUTES.nativeAddress(),e.value());assertEquals(8,h.placement.pool().state(127).routine());assertTrue(h.placement.pool().capture().slots().stream().anyMatch(x->x.id()==0x3A));assertEquals(1,h.bonus.orElseThrow().updateHudBonusByte());assertEquals(0,h.bonus.orElseThrow().timeBonusWord());}}
 @Test void matchingEndPublicationPreflightsAcceptOwnPortAndRejectPublicReentry()throws Exception{for(var a:actual()){var h=new Host(a);capsule(h,2);h.beforeAdopt=()->{h.lastAdoption.validateBefore();assertThrows(IllegalStateException.class,()->h.pass.runWalk(0));};h.walk();h.finish();assertFalse(h.frame.closed());}}
 @Test void originalRuntimeAndErrorKeepHudAndSourcePrefixBeforeFailedVelocityStore()throws Exception{for(var a:actual())for(Throwable original:List.of(new IllegalArgumentException("Recoil owner"),new AssertionError("Recoil owner"))){var h=new Host(a);capsule(h,2);h.beforeAdopt=()->{if(h.lastAdoption.endCall() instanceof CdR13Capsule.StoreCall c&&c.site()==CdR13Capsule.Site.BOUNCE_STORE_Y){if(original instanceof RuntimeException r)throw r;throw(Error)original;}};assertSame(original,assertThrows(Throwable.class,h::walk));assertEquals(0,h.level.updateHudTime());assertEquals(4,h.placement.pool().state(127).routine());assertEquals(-800,h.frame.state().motion().yVelocity());assertFalse(h.pass.isCurrentEndOperation(h.retainedEnd));assertThrows(IllegalStateException.class,h.lastAdoption::applyNative);}}
 @Test void staleFullFrameAndFull96RejectBeforeThePreparedHudStore()throws Exception{for(var a:actual())for(boolean pool:new boolean[]{false,true}){var h=new Host(a);capsule(h,2);h.beforeAdopt=()->{if(pool)h.placement.pool().write(h.placement.pool().state(126).moveByte(SUBTYPE,1));else h.frame.applyPreparedObjectSolidPublication(h.frame.prepareObjectPrimaryAngle(h.frame.environment().movement().globals().primaryAngle(),0x77));};assertThrows(IllegalArgumentException.class,h::walk);assertEquals(1,h.level.updateHudTime());}}
