 @Test void explicitlyConstructedOffscreenComponentCutInitializesThreeActual480Rows()throws Exception{for(var a:actual()){var h=new Host(a,4,400,2);results(h,2);h.walk();var rows=h.placement.pool().capture().slots().stream().filter(x->x.id()==0x3A).toList();assertEquals(3,rows.size());for(var row:rows){assertEquals(4,row.routine());assertEquals(480,row.word(RESULTS_TIMER_WORD));}assertEquals(2,rows.stream().filter(x->x.identity().wholeIndex()!=127).count());}}
 @Test void unconditionalClearPublishesUnknownToKnownZeroWithoutAReadOrFallback()throws Exception{for(var a:actual()){var h=new Host(a);results(h,8);assertTrue(h.flagsImage.value().isEmpty());h.walk();assertEquals(0,h.flagsImage.value().orElseThrow());assertEquals(1,h.frame.environment().movement().gates().timeZone());assertEquals(0x100,h.frame.environment().movement().gates().zoneAct());assertEquals(2,h.level.levelRestart());}}
 @Test void constructedNonActThreeTailStopsAtTheActualUnknownFlagsBsetPreimage()throws Exception{for(var a:actual()){var h=new Host(a,4,0,0);h.good=OptionalInt.of(1);results(h,8);var e=assertThrows(SonicCdAct3FutureObjectPass.Unowned.class,h::walk);assertEquals(SonicCdAct3FutureObjectPass.Boundary.RESULTS_FLAGS,e.boundary());assertTrue(h.flagsImage.value().isEmpty());assertEquals(0,h.good.orElseThrow());assertEquals(1,h.frame.environment().movement().gates().zoneAct());}}
 @Test void finalBonusUsesOriginalKachingMinimumDelayAndSharedTenPoints()throws Exception{for(var a:actual()){var h=new Host(a);h.bonus=Optional.of(new CdLevelHud.BonusValues(100,0,0));results(h,6);h.walk();assertEquals(0,h.bonus.orElseThrow().timeBonusWord());assertEquals(45,h.placement.pool().state(127).word(RESULTS_TIMER_WORD));assertEquals(10,h.score.score());assertTrue(h.sounds.stream().anyMatch(x->x instanceof SonicCdGameModule.PastResultsSound r&&r.sound()==CdResults.Sound.DRIVER_KACHING));}}
 @Test void explicitlyConstructedPastPeriodProducesPcmFadeBeforeActualResultsMusic()throws Exception{for(var a:actual()){var h=new Host(a,4,0,2,0);capsule(h,6);h.placement.pool().write(h.placement.pool().state(127).moveByte(LEVEL_END_TIMER,1));h.walk();var cpu=h.sounds.stream().filter(SonicCdGameModule.PastR13CapsuleSubCpu.class::isInstance).map(SonicCdGameModule.PastR13CapsuleSubCpu.class::cast).toList();assertEquals(List.of(CdR13Capsule.CpuCommand.FADE_PCM,CdR13Capsule.CpuCommand.RESULTS_MUSIC),cpu.stream().map(SonicCdGameModule.PastR13CapsuleSubCpu::command).toList());}}
 @Test void realExhaustedResultsFindKeepsNativeMusicControlsAndParentPrefix()throws Exception{for(var a:actual()){var h=new Host(a);for(int w=32;w<127;w++)h.placement.pool().write(h.placement.pool().state(w).moveByte(ID,0x15).moveByte(ROUTINE,8));capsule(h,6);h.placement.pool().write(h.placement.pool().state(127).moveByte(LEVEL_END_TIMER,1));var e=assertThrows(CdR13Capsule.UnownedCapsule.class,h::walk);assertEquals(CdR13Capsule.Boundary.RESULTS_ALLOCATION,e.boundary());assertEquals(8,h.placement.pool().state(127).routine());assertEquals(180,h.placement.pool().state(127).unsignedByte(LEVEL_END_TIMER));assertEquals(0xA1,h.frame.environment().controls().controlLocked());assertEquals(0,h.bonus.orElseThrow().updateHudBonusByte());assertTrue(h.sounds.stream().anyMatch(SonicCdGameModule.PastR13CapsuleSubCpu.class::isInstance));}}
 @Test void fourActualSeedSlotsRetainTheirPrefixThenParentAdvancesNormally()throws Exception{for(var a:actual()){var h=new Host(a);for(int w=32;w<123;w++)h.placement.pool().write(h.placement.pool().state(w).moveByte(ID,0x15).moveByte(ROUTINE,8));capsule(h,4);h.placement.pool().write(h.placement.pool().state(127).moveByte(LEVEL_END_TIMER,0));h.walk();assertEquals(6,h.placement.pool().state(127).routine());assertEquals(60,h.placement.pool().state(127).unsignedByte(LEVEL_END_TIMER));assertEquals(4,h.placement.pool().capture().slots().stream().filter(x->x.id()==0x15&&x.routine()==10).count());assertArrayEquals(CdR13CapsuleAssets.bind(a).restoredPalette().bytes().copy(),h.normal.slice(32,96).copy());}}
 private static void capsule(Host h,int routine){var m=CdR13CapsuleAssets.bind(h.assets);var p=h.placement.pool();h.seedDynamic(127,0x15,0);p.write(p.state(127).moveByte(ROUTINE,routine).moveByte(SPRITE_FLAGS,4).moveByte(PRIORITY,4).moveByte(WIDTH,32).moveByte(Y_RADIUS,24).moveByte(X_RADIUS,32).moveWord(X,0).moveWord(Y,0).moveWord(TILE,m.tileWord()).moveLong(MAPPINGS,m.mappingAddress()));}
 private static void results(Host h,int routine){var m=CdR13ResultsAssets.bind(h.assets,CdR13CapsuleAssets.bind(h.assets));h.seedDynamic(127,0x3A,0);var p=h.placement.pool();p.write(p.state(127).moveByte(ROUTINE,routine).moveLong(MAPPINGS,m.mappingAddress()).moveWord(TILE,0x83C4).moveByte(SPRITE_FLAGS,0));}
