        Object programme=new Object();CdRingGlobals ring=new CdRingGlobals(0,3,0,0,0,0,0,0);CdAssetBytes reserved=CdAssetBytes.copyOf(new byte[1984]),cpu=CdAssetBytes.copyOf(new byte[640]);Optional<CdObjectDrawQueue.CpuSat> completed=Optional.empty();List<SonicCdGameModule.PastSound> sounds=List.of();OptionalInt good=OptionalInt.of(0),projector=OptionalInt.empty();int scroll=0x33A5;CdPlayerBody.ContactGlobals contact=new CdPlayerBody.ContactGlobals(0,0,0);Optional<CdGlobalObjectAnimation.Extras> animations=Optional.empty();Object fence=new Object();Object bossHostFence=new Object(),bossCoreFence=new Object();OptionalInt bossFlags=OptionalInt.of(0),targetRight=OptionalInt.of(0x1000);int targetBottom=0x1000,targetLeft=0;CdOpeningObjectRuntime.ScoreGlobals score=new CdOpeningObjectRuntime.ScoreGlobals(0,5000,0);CdAssetBytes normal=CdAssetBytes.copyOf(new byte[128]);Object retainedEnd;CdR13Boss.Call retainedBoss;boolean active;Runnable beforeAdopt=()->{};Throwable fault;
        SonicCdAct3FutureObjectPass.Adoption lastAdoption;SonicCdAct3FutureObjectPass.PlcSubmission lastPlc;
        Host(CdR13FutureAssets a){this(a,new CdPlayerFrameRuntime.VIntClock(OptionalLong.of(0),0));}
