        public void adopt(SonicCdAct3FutureObjectPass.Adoption a){lastAdoption=a;a.validateBefore();if(retainedEnd==null&&a.endCall()!=null)retainedEnd=a.endCall();beforeAdopt.run();if(fault instanceof RuntimeException r)throw r;if(fault instanceof Error e)throw e;var next=a.next();var end=a.endNext();var nextHost=new Object();var nextCore=new Object();Object nextProgramme=programme;if(a.endCall() instanceof CdResults.ProgrammeStoreCall c&&c.field()==CdResults.ProgrammeField.GOOD_FUTURE_BYTE){nextProgramme=new Object();a.prepareEndProgramme(programme,nextProgramme);next=a.next();}var flagsReady=pass.isCurrentEndFlagsPublication(a)?new SonicCdAct3FutureObjectPass.ResultsFlagsImage(new Object(),end.flagsByte()):flagsImage;a.applyNative();if(end!=null){level=end.level();bonus=end.bonus();score=end.score();normal=end.normalPalette();unknown=end.unknownLevelByte();good=OptionalInt.of(end.goodFutureByte());flagsImage=flagsReady;}projector=next.projectorByte();programme=nextProgramme;endHostFence=nextHost;endCoreFence=nextCore;ring=next.ring();reserved=next.reservedSlots();cpu=next.cpuSat();completed=next.completedCpu();sounds=next.sounds();scroll=next.scrollLockWord();}
